30	  function canCreateAgents(agent: { permissions: Record<string, unknown> | null | undefined }) {
31	    if (!agent.permissions || typeof agent.permissions !== "object") return false;
32	    return Boolean((agent.permissions as Record<string, unknown>).canCreateAgents);
