41	  function deriveTrackedSkillRef(skill: SkillTelemetryInput): string | null {
42	    if (skill.sourceType === "skills_sh") {
43	      return skill.key;
44	    }
45	    if (skill.sourceType !== "github") {
46	      return null;
47	    }
48	    const hostname = asString(skill.metadata?.hostname);
49	    if (hostname !== "github.com") {
50	      return null;
51	    }
52	    return skill.key;
