55	  async function assertCanMutateCompanySkills(req: Request, companyId: string) {
56	    assertCompanyAccess(req, companyId);
57	
58	    if (req.actor.type === "board") {
59	      if (req.actor.source === "local_implicit" || req.actor.isInstanceAdmin) return;
60	      const allowed = await access.canUser(companyId, req.actor.userId, "agents:create");
61	      if (!allowed) {
62	        throw forbidden("Missing permission: agents:create");
63	      }
64	      return;
65	    }
66	
67	    if (!req.actor.agentId) {
68	      throw forbidden("Agent authentication required");
69	    }
